export const CODE_CRITIQUE_TOOL_NAME = "code_critique";

/**
 * Action discriminator generated by the SDK for the client-defined critique
 * tool (`ClientAction_<tool-name>`). Keep the SDK naming convention contained
 * here instead of repeating its generated class name throughout the frontend.
 */
export const CODE_CRITIQUE_ACTION_KIND =
  `ClientAction_${CODE_CRITIQUE_TOOL_NAME}` as const;

/**
 * Prefix of the machine-generated message the frontend posts back with the
 * critique result. Client tools are acknowledged by the agent-server before
 * the browser has done any work, so this message is the only channel for the
 * findings. The chat hides it (see `should-render-event.ts`) because the agent
 * relays the outcome in its own reply.
 */
export const CODE_CRITIQUE_RESULT_PREFIX = "[code-critique] ";

/** Ledger key namespace, so a replay of a tool call is not analysed twice. */
export const CODE_CRITIQUE_LEDGER_PREFIX = "openhands-code-critique:";
